        // Células com (i + j) % 2 == 0 são PARES (paridade 0)
        // Células com (i + j) % 2 == 1 são ÍMPARES (paridade 1)
        long cost1 = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int targetParity = ((i + j) % 2 == 0) ? 0 : 1;
                if ((g[i][j] % 2) != targetParity) {
                    cost1++;
                }
            }
        }

        int chosenOption = (cost0 <= cost1) ? 0 : 1;
        long minCost = (chosenOption == 0) ? cost0 : cost1;

        StringBuilder sb = new StringBuilder();
        sb.append(minCost).append("\n");

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int targetParity;
                if (chosenOption == 0) {
                    targetParity = ((i + j) % 2 == 0) ? 1 : 0;
                } else {
                    targetParity = ((i + j) % 2 == 0) ? 0 : 1;
                }

                int val = g[i][j];
                if ((val % 2) != targetParity) {
                    val++;
                }

                if (j > 0) sb.append(" ");
                sb.append(val);
            }
            sb.append("\n");
        }

        System.out.print(sb);
    }
}
